create table if not exists creator_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null, display_name text, ig_followers int default 252000, tiktok_followers int default 50000, daily_send_cap int default 20, auto_send boolean default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists brands (id uuid primary key default gen_random_uuid(), user_id uuid not null, name text not null, normalized_name text not null, domain text, sector text, status text default 'new', existing_partner boolean default false, dream_brand boolean default false, blocked boolean default false, do_not_contact boolean default false, fit_score int, deal_probability int, created_at timestamptz default now(), updated_at timestamptz default now(), unique(normalized_name), unique(domain));
create table if not exists brand_sources (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_id uuid references brands(id) on delete cascade, url text not null, title text, snippet text, confidence numeric, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists brand_contacts (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_id uuid references brands(id) on delete cascade, name text, email text, role text, confidence text, source_url text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists pitch_angles (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_id uuid references brands(id) on delete cascade, angle text not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists offer_packages (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_id uuid references brands(id) on delete cascade, package_name text, deliverables text, rate_anchor numeric, floor numeric, warnings text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists outreach_messages (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_id uuid references brands(id) on delete cascade, contact_id uuid references brand_contacts(id), channel text, status text default 'draft', subject text, body text, sent_at timestamptz, provider_message_id text, created_at timestamptz default now(), updated_at timestamptz default now(), unique(brand_id, contact_id, channel, status));
create table if not exists outreach_events (id uuid primary key default gen_random_uuid(), user_id uuid not null, outreach_message_id uuid references outreach_messages(id) on delete cascade, event_type text, payload jsonb, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists case_studies (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_name text, links text[], views int, reach int, engagement numeric, feedback text, results text, proof_points text[], created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists deals (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_id uuid references brands(id), stage text default 'negotiating', value numeric, travel_value numeric, status text default 'open', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists deal_terms (id uuid primary key default gen_random_uuid(), user_id uuid not null, deal_id uuid references deals(id) on delete cascade, deliverables text, usage_rights text, exclusivity text, ftc_disclosure text, warnings text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists agent_runs (id uuid primary key default gen_random_uuid(), user_id uuid not null, agent_name text, status text, input jsonb, output jsonb, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists gmail_connections (id uuid primary key default gen_random_uuid(), user_id uuid not null, gmail_email text, access_token text, refresh_token text, expires_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists content_examples (id uuid primary key default gen_random_uuid(), user_id uuid not null, platform text, url text, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists follow_up_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null, brand_id uuid references brands(id), outreach_message_id uuid references outreach_messages(id), due_at timestamptz, status text default 'due', created_at timestamptz default now(), updated_at timestamptz default now());
